void update_route(void)
{
    taskENTER_CRITICAL();
    shared.addr = new_addr;
    shared.len  = new_len;
    shared.ready = 1;
    taskEXIT_CRITICAL();
}

void HIGH_PRIO_IRQHandler(void)
{
    if (shared.ready)
        use_route(shared.addr, shared.len);
}

__attribute__((section(".noinit")))
struct crash_record g_crash;

void boot(void)
{
    if (g_crash.magic == 0x43524153u)
        report_crash(&g_crash);
}

__attribute__((section(".ramfunc")))
void flash_update(uint32_t addr, const uint8_t *data)
{
    qspi_erase_sector(addr);
    qspi_program(addr, data, 4096);
}
